		disposeAgentCreated = ctx.on("agent/created", async (payload) => {
			// 边界（显式且必须）：宿主把本监听器的抛错当作「否决这次会话创建」。一个连不上的 MCP
			// 服务器绝不能把用户挡在会话门外，所以这里把一切错误吞成日志——挂载失败本身由
